{"path":"assets/css/styles.css","content":"/* Minimal poetic palette, split diagonal layout */
:root{
  --bg:#fbfdfb; --muted:#6b6f6a; --accent:#5b8c6f; --ink:#123; --soft:#f4fbf7; --glass: rgba(255,255,255,0.7);
  --max-width:1100px; --radius:10px;
}
*{box-sizing:border-box}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial; color:var(--ink); background:var(--bg); margin:0; line-height:1.45}
.wrap{max-width:var(--max-width); margin:0 auto; padding:0 20px}
.site-header{display:flex; align-items:center; justify-content:space-between; padding:18px 24px; border-bottom:1px solid #e6eee6; background:linear-gradient(180deg,var(--soft),transparent)}
.brand .logo{font-weight:700; letter-spacing:0.6px}
.brand .tag{font-size:13px; color:var(--muted)}
.main-nav a{margin-left:14px; text-decoration:none; color:var(--ink); font-size:15px}
.main-nav a.cta{background:var(--accent); color:white; padding:8px 12px; border-radius:8px}

.hero{display:grid; grid-template-columns:1fr 1fr; gap:0; align-items:stretch}
.split-diagonal .panel{padding:48px}
.split-diagonal .left{background:transparent}
.split-diagonal .right{position:relative; overflow:hidden}
.pattern-wrap{position:absolute; inset:0; background-image:url('../assets/img/pattern.svg'); background-size:cover; opacity:0.14; transform:translateY(-6%)}
.snapshot{position:relative; z-index:2; background:var(--glass); padding:18px; border-radius:12px; margin:24px; box-shadow:0 6px 18px rgba(10,20,10,0.04)}
.lead{color:var(--muted); max-width:46ch}
.hero-ctas .btn{margin-right:8px}
.contact-inline{list-style:none; padding:0; margin-top:14px; display:flex; gap:12px; color:var(--muted)}

section{padding:48px 20px}
.what-expect .intro{color:var(--muted); max-width:54ch}
.inventory{margin-top:18px; background:white; border-radius:12px; padding:18px; box-shadow:0 6px 18px rgba(10,20,10,0.03)}
.inventory .areas{display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px}
.inventory label{display:flex; align-items:center; gap:8px; background:linear-gradient(180deg,#fff,#fbfffb); padding:8px; border-radius:8px}
.inventory-actions{margin-top:12px; display:flex; gap:8px}
.btn{background:#fff; border:1px solid #dfeee0; color:var(--ink); padding:9px 12px; border-radius:8px; cursor:pointer; text-decoration:none}
.btn.primary{background:var(--accent); color:#fff; border-color:transparent}
.btn.ghost{background:transparent; border-style:dashed}
.output{white-space:pre-wrap; background:#fbfffaff; padding:12px; border-radius:8px; margin-top:12px; border:1px dashed #e6efe7}

.gallery .cards{display:flex; gap:14px; margin-top:14px}
.card{flex:1; background:linear-gradient(180deg,#fff,#fcfff9); padding:18px; border-radius:12px; box-shadow:0 6px 20px rgba(10,20,10,0.03)}
.price{margin-top:10px; color:var(--accent); font-weight:700}

.objections .qas{display:grid; grid-template-columns:repeat(3,1fr); gap:12px}
.qa{background:#fff; padding:14px; border-radius:8px}
.qa h5{margin:0 0 6px 0}
.qa .ans{color:var(--muted); font-size:14px}

.planner{background:linear-gradient(180deg,#fff,#fbfff7); border-radius:12px; padding:18px}
.planner label{display:block; margin-top:12px}
.areas-grid{display:grid; gap:8px; grid-template-columns:repeat(4,1fr); margin-top:8px}
.planner-actions{display:flex; gap:8px; margin-top:12px}
.planner textarea{width:100%; padding:10px; border-radius:8px; border:1px solid #e6efe7}

.cta{background:var(--accent); color:white; padding:36px 20px; border-radius:12px; margin:20px}
.cta .big{background:#fff;color:var(--accent); padding:12px 18px; border-radius:12px; font-weight:700}
.tiny{font-size:12px; opacity:0.9}

.site-footer{border-top:1px solid #e6eee6; padding:20px}
.site-footer small{color:var(--muted)}n
@media(max-width:900px){
  .hero{grid-template-columns:1fr}
  .gallery .cards{flex-direction:column}
  .objections .qas{grid-template-columns:1fr}
  .areas-grid{grid-template-columns:repeat(2,1fr)}
  .inventory .areas{grid-template-columns:repeat(1,1fr)}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Session Planner and Whole-person Inventory
  function el(id){return document.getElementById(id)}

  // Inventory logic
  var invForm = el('inventory-form');
  var invGen = el('inventory-generate');
  var invOut = el('inventory-output');
  var invCopy = el('inventory-copy');

  function generateInventorySummary(areas){
    if(!areas.length) return 'No areas selected. Consider the parts of life you notice most.\n\nSuggested: pick 2–4 to focus on for the first visit.';
    var agenda = ['Intake & history (10–15m)'];
    // Prioritize tight items first
    areas.slice(0,4).forEach(function(a,i){
      agenda.push((i+1)+'. Explore: '+a+' (10–12m)');
    });
    agenda.push('Shared priorities & quick wins (5–10m)');
    agenda.push('Safety & referral check');

    var cadence = [];
    if(areas.length<=2) cadence.push('2–3 check-ins over 6–8 weeks; focus on early signals');
    else if(areas.length<=4) cadence.push('4 check-ins across 8–12 weeks; refine practices and measures');
    else cadence.push('Initial intensive (4 weeks) then transition to maintenance checks every 3–6 weeks');

    var txt = 'Whole-person inventory summary\n\nSelected areas: '+areas.join(', ')+'\n\nConsultation agenda:\n - '+agenda.join('\n - ')+'\n\nFollow-up cadence:\n - '+cadence.join('\n - ')+'\n\nNotes: Bring recent sleep, food, and movement notes where possible.';
    return txt;
  }

  invGen && invGen.addEventListener('click', function(){
    var checked = Array.from(invForm.querySelectorAll('input[name="area"]:checked')).map(function(i){return i.value});
    var summary = generateInventorySummary(checked);
    invOut.textContent = summary;
    invCopy.disabled = false;
  });

  invCopy && invCopy.addEventListener('click', function(){
    var txt = invOut.textContent || '';
    if(!txt) return;
    navigator.clipboard && navigator.clipboard.writeText(txt).then(function(){
      invCopy.textContent = 'Copied';
      setTimeout(function(){ invCopy.textContent = 'Copy summary' },1500);
    });
  });

  // Planner logic
  var planner = el('planner-form');
  var plannerBuild = el('planner-build');
  var plannerOut = el('planner-output');
  var plannerCopy = el('planner-copy');

  function buildPlan(){
    var pace = el('pace').value;
    var followups = Number(el('followups').value)||0;
    var notes = el('planner-notes').value.trim();
    var focuses = Array.from(planner.querySelectorAll('input[name="focus"]:checked')).map(function(i){return i.value});

    if(focuses.length>4) focuses = focuses.slice(0,4);

    var header = 'Personal session plan\n\nPace: '+(pace==='concise'? 'Concise (30-45m)': pace==='deep'? 'Deep (90m)': 'Standard (60m)');
    var body = '\nFocus areas: '+(focuses.length?focuses.join(', '): 'None selected')+'\n\nInitial steps:\n';

    if(focuses.length){
      focuses.forEach(function(f,i){
        body += '- '+(i+1)+'. Quick assessment of '+f+'; single testable suggestion\n';
      });
    } else {
      body += '- Review daily rhythms (sleep, food, movement) and set one micro-experiment\n';
    }

    body += '\nFollow-up plan:\n';
    if(followups>0){
      body += '- '+followups+' follow-up(s) planned across coming weeks; adjust frequency by early signals\n';
    } else {
      body += '- No scheduled follow-ups; consider 1 check-in in 2–4 weeks\n';
    }

    if(notes) body += '\nContext notes:\n'+notes+'\n';

    // integrate inventory if present
    var inventorySelected = Array.from(document.querySelectorAll('#inventory-form input[name="area"]:checked')).map(function(i){return i.value});
    if(inventorySelected.length){
      body += '\nFrom whole-person inventory: selected '+inventorySelected.join(', ')+'. Agenda and cadence will reflect these priorities.\n';
    }

    var closing = '\nNext practical step:\n- Book the chosen session and bring simple daily notes for 3–7 days.';

    return header+body+closing;
  }

  plannerBuild && plannerBuild.addEventListener('click', function(){
    var txt = buildPlan();
    plannerOut.textContent = txt;
    plannerCopy.disabled = false;
  });

  plannerCopy && plannerCopy.addEventListener('click', function(){
    var txt = plannerOut.textContent || '';
    if(!txt) return;
    navigator.clipboard && navigator.clipboard.writeText(txt).then(function(){
      plannerCopy.textContent = 'Copied';
      setTimeout(function(){ plannerCopy.textContent = 'Copy plan' },1500);
    });
  });

  // Small UX: limit focus choices to 4
  var focusInputs = Array.from(document.querySelectorAll('input[name="focus"]'));
  focusInputs.forEach(function(inp){
    inp.addEventListener('change', function(){
      var checked = focusInputs.filter(function(i){return i.checked});
      if(checked.length>4){
        this.checked = false; // refuse the fifth
        alert('Choose up to 4 focus areas');
      }
    });
  });

})();
"} 
